<?php declare(strict_types=1);
use Kulturhus\Verein\FinancePaymentAuthority;
use Kulturhus\Native\Language\InvoiceReviewMessages;
$invoiceReviewMessages??=isset($nativeAccess)?(new \Kulturhus\Native\Language\Catalog($db,$nativeAccess))->messages():[];
$approvalText=static fn(string$text,array$values=[]):string=>InvoiceReviewMessages::text($text,$invoiceReviewMessages,$values);
$approvalService=new \Kulturhus\Verein\InvoiceApprovals($db,(string)$_SESSION['actor']);$approval=$approvalService->state($r['id']);
$approvalSupplier=($receiptIsCredit??false)?null:($supplierLink??null);$approvalBank=($receiptIsCredit??false)?[]:($supplierBank??[]);$approvalCreditText=static fn(string$text):string=>\Kulturhus\Native\Language\TransferMessages::text($text,$transferMessages??[]);
$approvalDraft=in_array(input($_POST,'action'),['invoice-approve','invoice-approval-clarify','invoice-approval-withdraw'],true)&&input($_POST,'entry')===$r['id'];
$approvalAction=$approvalDraft?input($_POST,'action'):'';$approvalClarifyDraft=$approvalAction==='invoice-approval-clarify';$approvalWithdrawDraft=$approvalAction==='invoice-approval-withdraw';$approvalRecipient=$approvalSupplier['supplier_name']??$r['counterparty'];
$approvalFresh=$approvalDraft&&input($_POST,'approval_review_active')==='1';$approvalFirst=($invoiceReviewResult??[])['first']??null;
$approvalConflict=$approvalDraft&&(input($_POST,'snapshot_hash')!==$approval['hash']||input($_POST,'decision_id')!==$approval['decision_id']);
$approvalAvailable=match($approvalAction){'invoice-approve'=>$approval['can_approve'],'invoice-approval-clarify'=>$approval['can_withdraw'],'invoice-approval-withdraw'=>$approval['can_withdraw']&&($approval['last']['decision']??'')==='approved',default=>false};
$approvalRecovery=$approvalDraft&&($approvalConflict||!$approvalAvailable||($approvalFirst!==null&&!($invoiceReviewResult['active']??false)));
$approvalMarkers=hidden('entry',$r['id']).hidden('snapshot_hash',$approvalDraft?input($_POST,'snapshot_hash'):$approval['hash']).hidden('decision_id',$approvalDraft?input($_POST,'decision_id'):$approval['decision_id']).($approvalFresh?hidden('approval_review_active','1'):'');
$approvalKey=static fn(string$action):string=>$approvalAction===$action?input($_POST,'request_key'):bin2hex(random_bytes(16));
$approvalReadButton=static function()use($approvalText):void{?><button type="submit" class="btn btn-outline theme-secondary invoice-review-read" name="approval_read" value="1" formnovalidate><?=e($approvalText('Gespeicherten Prüfschritt lesen'))?></button><?php };
$approvalStatuses=['pending'=>'Noch nicht freigegeben','approved'=>'Freigegeben','changed'=>'Erneut prüfen','clarified'=>'Zur Klärung zurückgestellt','withdrawn'=>'Freigabe zurückgenommen','paid'=>'Bereits bezahlt','closed'=>'Abgeschlossen – keine Zahlungsfreigabe'];
?>
<section class="card" id="invoice-approval"><h2><?=e($approvalText('Prüfen'))?></h2><p class="invoice-approval-status"><strong><?=e($approvalText($approvalStatuses[$approval['status']]))?></strong></p>
<?php if($approvalRecovery):?>
<section class="invoice-review-recovery" data-invoice-review-recovery><h3><?=e($approvalText('Prüfschritt fortsetzen'))?></h3>
<p><?=e($approvalText('Die Angaben dieses Formulars bleiben erhalten. Den gespeicherten früheren Ausgang und den aktuellen Rechnungsstand getrennt prüfen. Lesen und Neuprüfen speichern keine Entscheidung und lösen keine Zahlung aus.'))?></p>
<?php if($approvalFirst):$firstClarified=$approvalFirst['decision']==='withdrawn'&&str_starts_with($approvalFirst['reason'],'[Klärung]');$firstLabel=$approvalFirst['decision']==='approved'?'Freigegeben':($firstClarified?'Zur Klärung zurückgestellt':'Zurückgenommen');$firstReason=$firstClarified?substr($approvalFirst['reason'],strlen('[Klärung] ')):$approvalFirst['reason']; ?>
<div class="invoice-review-earlier" data-invoice-review-earlier><h4><?=e($approvalText('Früher gespeicherter Ausgang'))?></h4><p><strong><?=e($approvalText($firstLabel))?></strong> · <?=e(dateDe(substr(localDateTime($approvalFirst['created_at']),0,10)).' · '.timeDe($approvalFirst['created_at']))?></p><?php if($firstReason!==''):?><p><?=e($firstReason)?></p><?php endif?><p><?=e($approvalText('Diese frühere Entscheidung bestätigt nicht automatisch neue oder geänderte Angaben dieses Formulars.'))?></p></div>
<?php endif?>
<form method="post" class="invoice-review-recovery-form"><?=csrf().hidden('action',$approvalAction).$approvalMarkers.hidden('request_key',input($_POST,'request_key')).hidden('reviewed',input($_POST,'reviewed'))?>
<p><strong><?=e($approvalText('Ursprünglicher Prüfschritt:'))?></strong> <?=e($approvalText(['invoice-approve'=>'Rechnung freigeben','invoice-approval-clarify'=>'Rückfrage zurückstellen','invoice-approval-withdraw'=>'Freigabe zurücknehmen'][$approvalAction]))?></p>
<?php if($approvalClarifyDraft||$approvalWithdrawDraft):?><label><?=e($approvalText('Angaben aus diesem Formular'))?><textarea class="form-control" name="reason" rows="4" maxlength="1000" <?= !$approvalService->canApprove()?'readonly':''?>><?=e(input($_POST,'reason'))?></textarea></label><?php endif?>
<div class="invoice-review-recovery-actions"><?php $approvalReadButton();if($approvalService->canApprove()):?>
<?php if($approvalFirst&&$approvalAvailable):?><button type="submit" class="btn btn-outline theme-secondary" name="approval_new" value="1" formnovalidate><?=e($approvalText('Neuen Prüfschritt mit aktuellen Originalen beginnen'))?></button>
<?php elseif(!$approvalFirst):?><button type="submit" class="btn btn-outline theme-secondary" name="approval_review" value="1" formnovalidate><?=e($approvalText('Aktuelle Originale neu prüfen'))?></button><?php endif?>
<?php endif?></div></form></section>
<?php endif?>
<?php if($approval['status']==='paid'):?><p><?=e($approvalText('Bereits bezahlt.'))?></p><?php elseif($approval['status']!=='closed'):?>
<dl class="data-list invoice-approval-summary"><dt><?=e($approvalText('Empfänger'))?></dt><dd><?=e($approvalRecipient!==''?$approvalRecipient:'–')?></dd><dt>IBAN</dt><dd><?=e(($receiptIsCredit??false)?$approvalCreditText('Die gespeicherte Bankverbindung des ursprünglichen Käufers wird im Zahlungsauftrag geschützt geprüft.'):(($approvalBank['iban']??'')!==''?$approvalBank['iban']:$approvalText('Nicht hinterlegt – am Original prüfen')))?></dd><dt><?=e($approvalText('Gesamtbetrag'))?></dt><dd><?=e(euro((int)$r['amount_cents']))?></dd></dl>
<?php if($approval['payment_state']==='partial'):?><p><?=e($approvalText('Teilzahlung: Rest prüfen.'))?></p><?php endif?>
<?php if(!$approval['can_approve']&&$approval['status']!=='approved'):?><p class="notice"><?=e($approvalText('Du kannst den Originalbeleg und diese Angaben hier prüfen. Freigeben darf der Kassenwart oder eine dafür berechtigte Person.'))?></p><?php endif?>
<?php if(!$approvalRecovery):?>
<?php if($approval['can_approve']&&($approval['status']!=='approved'||($approvalFresh&&$approvalAction==='invoice-approve'))):?>
<form method="post" class="invoice-approval-form"><?=csrf().hidden('action','invoice-approve').$approvalMarkers.hidden('request_key',$approvalKey('invoice-approve'))?><fieldset class="invoice-approval-decision"><legend><?=e($approvalText('Prüfung bestätigen'))?></legend><label class="invoice-approval-choice"><input class="check" type="checkbox" name="reviewed" value="1" required><span><strong><?=e($approvalText('Originalrechnung geprüft'))?></strong><small><?=e($approvalText('Empfänger, IBAN und Betrag stimmen'))?><?php if(!empty($reimbursement)&&!in_array($reimbursement['state'],['cancelled','waived'],true)&&!($receiptIsCredit??false)):?> · <?=e($approvalText('private Erstattung eingeschlossen'))?><?php endif?>.</small></span></label></fieldset><button class="btn btn-solid theme-primary invoice-approval-submit"><?=e($approvalText('Rechnung freigeben'))?></button><?php $approvalReadButton();?></form>
<?php endif?>
<?php if(($approval['can_approve']&&$approval['status']!=='approved')||($approvalFresh&&$approvalClarifyDraft&&$approval['can_withdraw'])):?>
<details class="invoice-approval-clarify" <?=$approvalClarifyDraft?'open':''?>><summary><?=e($approvalText('Angabe stimmt nicht'))?></summary><form method="post" class="invoice-approval-form"><?=csrf().hidden('action','invoice-approval-clarify').$approvalMarkers.hidden('request_key',$approvalKey('invoice-approval-clarify'))?><label><?=e($approvalText('Was muss geklärt werden?'))?><textarea class="form-control" name="reason" required maxlength="1000" rows="3" placeholder="<?=e($approvalText('Betrag, Empfänger oder IBAN'))?>"><?=e($approvalClarifyDraft?input($_POST,'reason'):'')?></textarea></label><button type="submit" class="btn btn-outline theme-secondary secondary"><?=e($approvalText('Zurückstellen'))?></button><?php $approvalReadButton();?></form></details>
<?php endif?>
<?php endif?>
<?php if($approval['status']==='approved'):?><div class="invoice-approval-next"><strong><?=e($approvalText('Freigegeben'))?></strong><p><?=e($approvalText('Zahlung unten.'))?></p><details class="invoice-payment-alternatives"><summary><?=e($approvalText('Andere Zahlungsart'))?></summary><div class="actions"><a class="btn btn-outline theme-secondary button secondary" href="<?=e(url(receiptPaymentContext($r['id'],$_GET)))?>#invoice-payment"><?=e($approvalText('Umsatz zuordnen'))?></a><a class="btn btn-outline theme-secondary button secondary" href="<?=e(url(array_replace(receiptPaymentContext($r['id'],$_GET,false),['manual_payment'=>1])))?>#manual-payment"><?=e($approvalText('Zahlung manuell erfassen'))?></a></div></details></div><?php endif?>
<?php if(!$approvalRecovery&&$approval['can_withdraw']&&$approval['last']&&$approval['last']['decision']==='approved'):?>
<details <?=$approvalWithdrawDraft?'open':''?>><summary><?=e($approvalText('Freigabe zurücknehmen'))?></summary><form method="post" class="invoice-approval-form"><?=csrf().hidden('action','invoice-approval-withdraw').$approvalMarkers.hidden('request_key',$approvalKey('invoice-approval-withdraw'))?><label><?=e($approvalText('Grund'))?><input class="form-control" name="reason" required maxlength="1000" value="<?=e($approvalWithdrawDraft?input($_POST,'reason'):'')?>"></label><button class="btn btn-outline theme-secondary secondary"><?=e($approvalText('Freigabe mit Grund zurücknehmen'))?></button><?php $approvalReadButton();?></form></details>
<?php endif;endif?>
<?php $approvalHistory=$approvalService->history($r['id']);if($approvalHistory):?>
<details><summary><?=e($approvalText('Freigabeverlauf · {count} Entscheidungen',['count'=>count($approvalHistory)]))?></summary><p><?=e($approvalText('Vorherige Entscheidungen bleiben erhalten. Der Export „Belegpaket“ enthält die Prüfstände und zugehörigen verfügbaren Dateifassungen.'))?></p><ul>
<?php foreach($approvalHistory as$decision):$authority=json_decode($decision['office_evidence'],true);$clarification=$decision['decision']==='withdrawn'&&str_starts_with($decision['reason'],'[Klärung]');?><li><strong><?=e($approvalText($decision['decision']==='approved'?'Freigegeben':($clarification?'Zur Klärung zurückgestellt':'Zurückgenommen')))?></strong> · <?=e(dateDe(substr(localDateTime($decision['created_at']),0,10)).' · '.timeDe($decision['created_at']).' '.$approvalText('Uhr'))?> · <?=e($authority['actor_name']??$decision['actor_id'])?> · <?=e(FinancePaymentAuthority::label(is_array($authority)?$authority:[]))?><?php if($decision['reason']!==''):?><p><?=e($clarification?substr($decision['reason'],strlen('[Klärung] ')):$decision['reason'])?></p><?php endif?><details><summary><?=e($approvalText('Geprüften Stand anzeigen'))?></summary><p><?=e($approvalText('Entscheidung {number}',['number'=>(int)$decision['id']]))?> · <?=e($approvalText('Prüfsumme'))?> <code class="doc-hash" style="overflow-wrap:anywhere"><?=e($decision['snapshot_hash'])?></code></p><?php $decisionSnapshot=json_decode($decision['snapshot'],true);?><p><?=e(euro((int)$decisionSnapshot['entry']['amount_cents']))?> · <?=e($approvalText('{count} Dateifassungen.',['count'=>count($decisionSnapshot['documents'])]))?></p></details></li><?php endforeach?>
</ul></details><?php endif?></section>
